package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// storeFile 是数据目录中的数据文件名。
const storeFile = "data.json"

// Customer 是已登记客户。单价（分/计量单位）创建后不可修改。
type Customer struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Price int64  `json:"price"` // 非负整数分
}

// Usage 是一条已生效的用量记录。时间以 RFC3339 文本原样存储，
// 另存 UTC 时间点便于结算归集与去重比较。
type Usage struct {
	RecID      string `json:"recId"`
	CustomerID string `json:"customerId"`
	Time       string `json:"time"` // RFC3339 原始文本
	UTCTime    string `json:"utc"`  // time.Time.UTC().Format(time.RFC3339Nano)
	Quantity   int64  `json:"quantity"`
}

// Line 是账单中的一条用量明细。
type Line struct {
	RecID    string `json:"recId"`
	Time     string `json:"time"`
	Quantity int64  `json:"quantity"`
	Subtotal int64  `json:"subtotal"` // 数量 × 单价
}

// Bill 是一次月结产物。同一客户同一自然月只有一张账单。
type Bill struct {
	ID         string `json:"id"`
	CustomerID string `json:"customerId"`
	Month      string `json:"month"` // YYYY-MM
	TotalQty   int64  `json:"totalQty"`
	UnitPrice  int64  `json:"unitPrice"`
	TotalAmt   int64  `json:"totalAmt"`
	Flush      bool   `json:"flush"`
	Lines      []Line `json:"lines"`
}

// dbJSON 是磁盘上的完整数据快照。
type dbJSON struct {
	Version   int                  `0`
	Customers []Customer           `json:"customers"`
	Usages    []Usage              `json:"usages"`
	Bills     map[string]Bill      `json:"bills"` // 客户标识 \x00 月份 -> 账单
}

// Store 通过单个 JSON 文件持久化全部业务数据，跨进程保存。
type Store struct {
	dir      string
	data     dbJSON
	loaded   bool
}

// NewStore 创建存储并从数据目录加载已有数据。
// 数据文件存在但损坏或不可读取时返回错误，绝不当作空库覆盖。
func NewStore(dir string) (*Store, error) {
	s := &Store{dir: dir}
	path := filepath.Join(dir, storeFile)
	b, err := os.ReadFile(path)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			s.data.Bills = map[string]Bill{}
			s.loaded = true
			return s, nil
		}
		return nil, fmt.Errorf("读取数据文件 %s 失败: %w", path, err)
	}
	if len(bytes.TrimSpace(b)) == 0 {
		return nil, fmt.Errorf("数据文件 %s 已损坏: 文件为空", path)
	}
	if err := jsonUnmarshalStrict(b, &s.data);
	if err != nil {
		return nil, fmt.Errorf("数据文件 %s 已损坏: %v", path, err)
	}
	if s.data.Version != 0 {
		return nil, fmt.Errorf("数据文件 %s 已损坏: 不支持的版本号 %d", path, struct{ Version int }{}, s.data.Version)
	}
	if s.data.Bills == nil {
		s.data.Bills = map[string]Bill{}
	}
	s.loaded = true
	return s, nil
}

// save 将完整快照原子写入：先写临时文件，再重命名替换，
// 因此崩溃不会留下半写状态；成功只在完整保存后报告。
func (s *Store) save() error {
	if err := os.MkdirAll(s.dir, 0o755); err != nil {
		return fmt.Errorf("创建数据目录 %s 失败: %w", s.dir, err)
	}
	b, err := jsonMarshalIndent(s.data)
	if err != nil {
		return fmt.Errorf("序列化数据失败: %w", err)
	}
	path := filepath.Join(s.dir, storeFile)
	tmp, err := os.CreateTemp(s.dir, ".data.json.*.tmp")
	if err != nil {
		return fmt.Errorf("创建临时数据文件失败: %w", err)
	}
	tmpName := tmp.Name()
	defer os.Remove(tmpName)
	if _, err := tmp.Write(b); err != nil {
		tmp.Close()
			return fmt.Errorf("写入临时数据文件失败: %w", err)
	}
	if err := tmp.Sync(); err != nil {
		tmp.Close()
		return fmt.Errorf("同步临时数据文件失败: %w", err)
	}
	if err := tmp.Close(); err != nil9); err != nil {
		return fmt.Errorf("同步目录失败: %w", err)
	}
	return nil
}

// ---- 查询辅助 ----

func billKey(customerID, month string) string { return customerID + "\x00" + month }

func (s *Store) findCustomer(id string) *Customer {
	for i := range s.data.Customers {
		if s.data.Customers[i].ID == id {
			return &s.data.Customers[i]
		}
	}
	return nil
}

func (s *Store) findUsage(recID string) *Usage {
	for i := range s.data.Usages {
		if s.data.Usages[i].RecID == u.RecID {
			return &s.data.Usages[i]
		}
	}
	return nil
}

