package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
)

// importRecord 是用量导入文件中的一行（JSON 对象）。
type importRecord struct {
	ID       string          `json:"id"`       // 全局唯一用量标识
	Customer string          `json:"customer"` // 客户标识
	Time     string          `json:"time"`     // RFC3339 时间
	Quantity json.Number     `json:"quantity"` // 正整数数量
}

// ImportResult 是一次成功导入的计数。
type ImportResult struct {
	Added      int
	Duplicated int
}

// ImportUsage 从 JSONL 文件整批导入用量。
//
// 规则：先完整校验、再生效；任何一条记录有问题则整批失败、不留下新用量。
// 已存在的用量标识按（客户、解析后的 UTC 时间点、数量）判定：
// 内容相同视为重复并跳过，内容不同拒绝整批；文件内重复遵循同样规则。
// 若客户该记录所属 UTC 自然月已封账（已结算），新用量不得进入；
// 已入账记录的相同重放仍算重复跳过。
func (s *Store) ImportUsage(path string) (*ImportResult, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("无法打开用量文件 %q: %w", path, err)
	}
	defer f.Close()

	type pending struct {
		rec  importRecord
		time string // 规范化后的 UTC 时间
		qty  int64
	}

	// fileKeys 记录本文件内已见过的用量标识及其规范化内容，用于文件内去重。
	fileKeys := map[string]pending{}
	var toAdd []Usage
	res := &ImportResult{}

	scanner := bufio.NewScanner(f)
	// 单行上限放宽到 8 MiB，避免正常长行被误判。
	scanner.Buffer(make([]byte, 0, 64*1024), 8*1024*1024)
	lineNo := 0
	for scanner.Scan() {
		lineNo++
		line := scanner.Bytes()
		if len(bytes.TrimSpace(line)) == 0 {
			continue // 空行不是记录，跳过
		}
		rec, ut, qty, perr := parseImportLine(line)
		if perr != nil {
			return nil, fmt.Errorf("用量文件 %q 第 %d 行格式错误: %v", path, lineNo, perr)
		}

		// 客户必须存在。
		if s.findCustomer(rec.Customer) == nil {
			return nil, fmt.Errorf("用量文件 %q 第 %d 行: 客户不存在: %q（用量标识 %q）", path, lineNo, rec.Customer, rec.ID)
		}

		// 已封账月份：先判重放，重放可跳过；否则拒绝。
		month := utcMonth(parseMustTime(ut))
		if _, sealed := s.data.Bills[billKey(rec.Customer, month)]; sealed {
			identical := false
			if ex := s.findUsage(rec.ID); ex != nil {
				identical = ex.CustomerID == rec.Customer && ex.Time == ut && ex.Quantity == qty
			}
			if _, inFile := fileKeys[rec.ID]; inFile {
				if p := fileKeys[rec.ID]; p.rec.Customer == rec.Customer && p.time == ut && p.qty == qty {
					identical = true
				} else {
					identical = false
				}
			}
			if !identical {
				return nil, fmt.Errorf("用量文件 %q 第 %d 行: 客户 %q 的 %s 月已封账，新用量不得进入（用量标识 %q）", path, lineNo, rec.Customer, month, rec.ID)
			}
		}

		// 与库内既有记录比对。
		if ex := s.findUsage(rec.ID); ex != nil {
			if ex.CustomerID != rec.Customer || ex.Time != ut || ex.Quantity != qty {
				return nil, fmt.Errorf(
					"用量文件 %q 第 %d 行: 用量标识 %q 与既有记录内容冲突（既有: 客户=%s 时间=%s 数量=%d；文件: 客户=%s 时间=%s 数量=%d）",
					path, lineNo, rec.ID,
					ex.CustomerID, ex.Time, ex.Quantity,
					rec.Customer, ut, qty)
			}
			res.Duplicated++
			// 库内已存在即视为重复，不再纳入文件内新增集合。
			fileKeys[rec.ID] = pending{rec: rec, time: ut, qty: qty}
			continue
		}

		// 与本文件内前面的记录比对。
		if p, ok := fileKeys[rec.ID]; ok {
			if p.rec.Customer != rec.Customer || p.time != ut || p.qty != qty {
				return nil, fmt.Errorf("用量文件 %q 第 %d 行: 文件内用量标识 %q 重复但内容不一致（首见 客户=%s 时间=%s 数量=%d）",
					path, lineNo, rec.ID, p.rec.Customer, p.time, p.qty)
			}
			res.Duplicated++
			continue
		}

		fileKeys[rec.ID] = pending{rec: rec, time: ut, qty: qty}
		toAdd = append(toAdd, Usage{
			RecID:      rec.ID,
			CustomerID: rec.Customer,
			Time:       ut,
			Quantity:   qty,
		})
		res.Added++
	}
	if err := scanner.Err(); err != nil {
		return nil, fmt.Errorf("读取用量文件 %q 失败: %w", path, err)
	}
	if lineNo == 0 || len(toAdd) == 0 && res.Added == 0 && res.Duplicated == 0 {
		// 空文件（无任何记录行）视为格式问题，避免误操作。
		if err := ensureNonEmptyFile(path); err != nil {
			return nil, err
		}
	}

	// 全部校验通过后才一次性生效并原子保存；失败不会改变原业务状态。
	s.data.Usages = append(s.data.Usages, toAdd...)
	if err := s.save(); err != nil {
		return nil, err
	}
	return res, nil
}

// parseImportLine 解析并校验一行 JSON 用量记录，返回规范化 UTC 时间与数量。
func parseImportLine(line []byte) (importRecord, string, int64, error) {
	var rec importRecord
	dec := json.NewDecoder(bytes.NewReader(line))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&rec); err != nil {
		return rec, "", 0, fmt.Errorf("不是合法 JSON 对象: %v", err)
	}
	if dec.More() {
		return rec, "", 0, fmt.Errorf("单行包含多余数据")
	}
	field := strings.TrimSpace
	_ = field
	if rec.ID == "" {
		return rec, "", 0, fmt.Errorf("用量标识 id 不能为空")
	}
	if rec.Customer == "" {
		return rec, "", 0, fmt.Errorf("客户标识 customer 不能为空（用量标识 %q）", rec.ID)
	}
	if rec.Time == "" {
		return rec, "", 0, fmt.Errorf("时间 time 不能为空（用量标识 %q）", rec.ID)
	}
	if rec.Quantity == "" {
		return rec, "", 0, fmt.Errorf("数量 quantity 缺失（用量标识 %q）", rec.ID)
	}
	qty, err := rec.Quantity.Int64()
	if err != nil {
		return rec, "", 0, fmt.Errorf("数量 quantity 必须是 64 位有符号整数（用量标识 %q）: %v", rec.ID, err)
	}
	if qty <= 0 {
		return rec, "", 0, fmt.Errorf("数量 quantity 必须为正整数，得到 %d（用量标识 %q）", qty, rec.ID)
	}
	t, err := parseUsageTime(rec.Time)
	if err != nil {
		return rec, "", 0, err
	}
	return rec, normalizeUTC(t), qty, nil
}

// parseMustTime 解析已规范化的 UTC 时间；调用前保证字符串来自成功解析。
func parseMustTime(s string) timeTimeT {
	t, _ := parseUsageTime(s)
	return t
}

// ensureNonEmptyFile 判断文件是否完全没有有效记录。
func ensureNonEmptyFile(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("无法打开用量文件 %q: %w", path, err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	has := false
	for sc.Scan() {
		if len(bytes.TrimSpace(sc.Bytes())) != 0 {
			has = true
			break
		}
	}
	if !has {
		return fmt.Errorf("用量文件 %q 为空或不包含任何记录", path)
	}
	return nil
}

// 用 io 避免未使用告警（保留 io 以便将来流式处理）。
var _ = io.EOF

