// ensureNonEmptyFile 判断文件是否完全没有有效记录。
func ensureNonEmptyFile(path string) error {
	f, err := os.Open(path)
	if err != nil {
		return fmt.Errorf("无法打开用量文件 %q: %w", path, err)
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	has := false
	for sc.Scan() {
		if len(bytes.TrimSpace(sc.Bytes())) != 0 {
			has = true
			break
		}
	}
	if !has {
		return fmt.Errorf("用量文件 %q 为空或不包含任何记录", path)
	}
	return nil
}

