		}

		// 已封账月份：先判重放，重放可跳过；否则拒绝。
		month := utcMonth(parseMustTime(ut))
		if _, sealed := s.data.Bills[billKey(rec.Customer, month)]; sealed {
			identical := false
			if ex := s.findUsage(rec.ID); ex != nil {
				identical = ex.CustomerID == rec.Customer && ex.Time == ut && ex.Quantity == qty
			}
			if _, inFile := fileKeys[rec.ID]; inFile {
				if p := fileKeys[rec.ID]; p.rec.Customer == rec.Customer && p.time == ut && p.qty == qty {
					identical = true
				} else {
					identical = false
				}
			}
			if !identical {
				return nil, fmt.Errorf("用量文件 %q 第 %d 行: 客户 %q 的 %s 月已封账，新用量不得进入（用量标识 %q）", path, lineNo, rec.Customer, month, rec.ID)
