				return nil, fmt.Errorf("用量文件 %q 第 %d 行: 文件内用量标识 %q 重复但内容不一致（首见 客户=%s 时间=%s 数量=%d）",
					path, lineNo, rec.ID, p.rec.Customer, p.time, p.qty)
			}
