		return nil, fmt.Errorf("读取用量文件 %q 失败: %w", path, err)
	}
	if lineNo == 0 || len(toAdd) == 0 && res.Added == 0 && res.Duplicated == 0 {
		// 空文件（无任何记录行）视为格式问题，避免误操作。
		if err := ensureNonEmptyFile(path); err != nil {
			return nil, err
		}
	}

	// 全部校验通过后才一次性生效并原子保存；失败不会改变原业务状态。
	s.data.Usages = append(s.data.Usages, toAdd...)
	if err := s.save(); err != nil {
