			return fail(stderr, "--help 只能单独使用")
		default:
			goto dispatch
		}
	}
dispatch:
	if len(rest) == 0 {
		return fail(stderr, "缺少命令；可用命令: register, import, settle, bill（使用 --help 查看说明）")
	}
