	if strings.HasPrefix(cmd, "-") {
		return fail(stderr, "未知选项 %q；使用 --help 查看帮助", cmd)
	}
	if dataDir == "" {
		dataDir = ".planbill"
	}

	store, err := NewStore(dataDir)
	if err != nil {
		return fail(stderr, "%v", err)
	}

	switch cmd {
